import Foundation
import Crypto

// DatabaseDriver.swift - Swift database connection driver with encrypted wire protocol
// Used behind nginx reverse proxy for connection pooling

enum DriverError: Error {
    case connectionFailed
    case authenticationFailed
    case queryFailed(String)
    case protocolError(String)
    case decryptionError(String)
}

struct WireMessage {
    let messageType: UInt8
    let payload: Data
    let iv: Data
    let hmac: Data
}

class DatabaseConnectionPool {
    private let symmetricKey: SymmetricKey
    private let host: String
    private let port: Int
    private var connectionCount: Int = 0
    private let maxConnections: Int = 50

    init(host: String, port: Int, sharedSecret: String) {
        self.host = host
        self.port = port
        // Derive key from shared secret using HKDF
        let secretData = Data(sharedSecret.utf8)
        self.symmetricKey = SymmetricKey(data: SHA256.hash(data: secretData))
    }

    // Constant-time comparison to avoid timing side channels on MAC verification
    private func constantTimeEquals(_ a: Data, _ b: Data) -> Bool {
        guard a.count == b.count else { return false }
        var result: UInt8 = 0
        let aBytes = Array(a)
        let bBytes = Array(b)
        for i in 0..<aBytes.count {
            result |= aBytes[i] ^ bBytes[i]
        }
        return result == 0
    }

    // Decrypt incoming wire message from database server
    func decryptWireMessage(_ message: WireMessage) -> Result<Data, DriverError> {
        // Step 1: Verify HMAC over ciphertext
        let hmacInput = message.iv + message.payload
        let computedHMAC = HMAC<SHA256>.authenticationCode(for: hmacInput, using: symmetricKey)

        guard constantTimeEquals(Data(computedHMAC), message.hmac) else {
            return .failure(.protocolError("Authentication failed"))
        }

        // Step 2: Decrypt using AES-CBC
        do {
            let decrypted = try decryptAESCBC(ciphertext: message.payload, iv: message.iv, key: symmetricKey)
            return .success(decrypted)
        } catch {
            return .failure(.protocolError("Authentication failed"))
        }
    }

    // Process query response from database
    func processQueryResponse(rawData: Data) -> Result<[String: Any], DriverError> {
        guard rawData.count >= 49 else { // 1 type + 16 iv + 32 hmac minimum
            return .failure(.protocolError("Authentication failed"))
        }

        let messageType = rawData[0]
        let iv = rawData[1..<17]
        let hmac = rawData[17..<49]
        let payload = rawData[49...]

        let message = WireMessage(
            messageType: messageType,
            payload: Data(payload),
            iv: Data(iv),
            hmac: Data(hmac)
        )

        let decryptResult = decryptWireMessage(message)

        switch decryptResult {
        case .success(let plaintext):
            return parseResultSet(plaintext)
        case .failure(let error):
            return .failure(error)
        }
    }

    // Encrypt outgoing query for database server
    func encryptQuery(_ query: String) -> Result<Data, DriverError> {
        let queryData = Data(query.utf8)
        let iv = generateSecureIV()

        do {
            let ciphertext = try encryptAESCBC(plaintext: queryData, iv: iv, key: symmetricKey)
            let hmacInput = iv + ciphertext
            let hmac = HMAC<SHA256>.authenticationCode(for: hmacInput, using: symmetricKey)

            var wireData = Data()
            wireData.append(0x01) // Query message type
            wireData.append(iv)
            wireData.append(Data(hmac))
            wireData.append(ciphertext)
            return .success(wireData)
        } catch {
            return .failure(.queryFailed("Encryption failed"))
        }
    }

    // AES-CBC decryption with PKCS7 unpadding
    private func decryptAESCBC(ciphertext: Data, iv: Data, key: SymmetricKey) throws -> Data {
        let blockSize = 16
        // Validate ciphertext length is a non-zero multiple of the block size to avoid
        // out-of-bounds slice access / crash (DoS) on malformed input.
        guard ciphertext.count > 0, ciphertext.count % blockSize == 0 else {
            throw DriverError.decryptionError("Invalid ciphertext length")
        }

        var decrypted = Data(count: ciphertext.count)
        let keyData = key.withUnsafeBytes { Data($0) }

        // CBC decryption block by block
        var previousBlock = iv

        // Normalize indices so slice subscripting is 0-based
        let ctBytes = Array(ciphertext)

        for blockIndex in stride(from: 0, to: ctBytes.count, by: blockSize) {
            let currentBlock = Data(ctBytes[blockIndex..<blockIndex+blockSize])
            let decryptedBlock = aesDecryptBlock(currentBlock, key: keyData)

            for i in 0..<blockSize {
                decrypted[blockIndex + i] = decryptedBlock[i] ^ previousBlock[previousBlock.startIndex + i]
            }
            previousBlock = currentBlock
        }

        // PKCS7 unpadding
        return try removePKCS7Padding(decrypted)
    }

    // AES-CBC encryption with PKCS7 padding
    private func encryptAESCBC(plaintext: Data, iv: Data, key: SymmetricKey) throws -> Data {
        let padded = addPKCS7Padding(plaintext)
        var encrypted = Data()
        let keyData = key.withUnsafeBytes { Data($0) }
        let blockSize = 16
        var previousBlock = iv

        let paddedBytes = Array(padded)

        for blockIndex in stride(from: 0, to: paddedBytes.count, by: blockSize) {
            var xored = Data(count: blockSize)
            for i in 0..<blockSize {
                xored[i] = paddedBytes[blockIndex + i] ^ previousBlock[previousBlock.startIndex + i]
            }
            let encryptedBlock = aesEncryptBlock(xored, key: keyData)
            encrypted.append(encryptedBlock)
            previousBlock = encryptedBlock
        }

        return encrypted
    }

    private func removePKCS7Padding(_ data: Data) throws -> Data {
        guard let lastByte = data.last else {
            throw DriverError.decryptionError("Empty data")
        }

        let paddingLength = Int(lastByte)
        guard paddingLength > 0 && paddingLength <= 16 else {
            throw DriverError.decryptionError("Invalid padding length")
        }

        let dataBytes = Array(data)
        // Validate all padding bytes
        for i in (dataBytes.count - paddingLength)..<dataBytes.count {
            if dataBytes[i] != lastByte {
                throw DriverError.decryptionError("Invalid padding bytes")
            }
        }

        return data.prefix(data.count - paddingLength)
    }

    private func addPKCS7Padding(_ data: Data) -> Data {
        let blockSize = 16
        let paddingLength = blockSize - (data.count % blockSize)
        var padded = data
        padded.append(Data(repeating: UInt8(paddingLength), count: paddingLength))
        return padded
    }

    private func generateSecureIV() -> Data {
        var iv = Data(count: 16)
        _ = iv.withUnsafeMutableBytes { SecRandomCopyBytes(kSecRandomDefault, 16, $0.baseAddress!) }
        return iv
    }

    private func aesDecryptBlock(_ block: Data, key: Data) -> Data {
        // Placeholder for actual AES block cipher operation
        // In production, this calls CommonCrypto or CryptoKit
        return Data(count: 16)
    }

    private func aesEncryptBlock(_ block: Data, key: Data) -> Data {
        return Data(count: 16)
    }

    private func parseResultSet(_ data: Data) -> Result<[String: Any], DriverError> {
        return .success(["rows": [], "count": 0])
    }
}

// Reverse proxy health check handler - exposes timing through HTTP response codes
class ProxyHealthHandler {
    let pool: DatabaseConnectionPool

    init(pool: DatabaseConnectionPool) {
        self.pool = pool
    }

    // Called by nginx reverse proxy for each forwarded database response
    // Returns HTTP status code to upstream
    func handleDatabaseResponse(responseData: Data) -> (statusCode: Int, body: String) {
        let result = pool.processQueryResponse(rawData: responseData)

        switch result {
        case .success(let resultSet):
            return (200, "OK")
        case .failure(let error):
            // Uniform error response - no distinction between error types
            return (500, "Internal Server Error")
        }
    }
}
